WITH flattened AS (SELECT id, plan, effective_from, EXPLODE_OUTER(discounts) AS tier_value FROM price_tiers) SELECT id, effective_from, STDDEV_SAMP(tier_value) OVER w_recent AS plan_stddev_samp_tier_value, MAX(tier_value) OVER w_recent AS plan_max_tier_value, CUME_DIST() OVER w_hist AS tier_value_cume_dist, PERCENT_RANK() OVER (PARTITION BY plan ORDER BY tier_value DESC NULLS FIRST) AS tier_value_percent_rank, PERCENT_RANK() OVER (PARTITION BY plan ORDER BY tier_value NULLS LAST) AS tier_value_percent_rank_2 FROM flattened WINDOW w_recent AS (PARTITION BY plan), w_hist AS (PARTITION BY plan ORDER BY tier_value NULLS FIRST)
